                'CREATE TABLE center_recovery (id VARCHAR(32) NOT NULL PRIMARY KEY, slot INTEGER NULL UNIQUE, actor VARCHAR(32) NOT NULL, proof VARCHAR(200) NOT NULL, state VARCHAR(20) NOT NULL, kind_index INTEGER NOT NULL, cursor VARCHAR(32) NOT NULL, started_at BIGINT NOT NULL, reviewed_at BIGINT NULL, completed_at BIGINT NULL, review_sha256 VARCHAR(64) NOT NULL)',
                'CREATE TABLE center_recovery_subject (recovery_id VARCHAR(32) NOT NULL, kind VARCHAR(20) NOT NULL, subject_id VARCHAR(32) NOT NULL, sha256 VARCHAR(64) NOT NULL, approved INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (recovery_id, kind, subject_id), FOREIGN KEY (recovery_id) REFERENCES center_recovery(id))',
                'CREATE TABLE center_registration_attempt (source_hash VARCHAR(64) NOT NULL PRIMARY KEY, window_started BIGINT NOT NULL, attempts INTEGER NOT NULL CHECK (attempts >= 1 AND attempts <= 60))',
                'CREATE INDEX center_registration_window ON center_registration_attempt (window_started)',
            ],
            default => throw new \InvalidArgumentException('center_database_invalid'),
        };
    }
}
